return items.map(item => {
  // 1. 抓取所需欄位
  const invoiceNumber = item.json['發票號碼'] || item.json.col_1 || '';
  const taxID = item.json['發票統編'] || item.json.col_2 || ''; 
  const companyName = item.json['發票公司'] || item.json.col_3 || '';
  const invoiceDate = item.json['發票日期'] || ''; // 抓取發票日期

  const style = 3;
  const dataObj = {
    "type": "invoice",
    "invoice_number": invoiceNumber,
    "download_style": style 
  };

  // 2. 動態計算發票期別 (將西元年轉為民國期別，如 20260525 轉為 11506)
  let period = "11506"; // 預設值
  if (invoiceDate) {
    const dateStr = String(invoiceDate).replace(/\D/g, ''); // 確保只留數字
    if (dateStr.length >= 8) {
      const year = parseInt(dateStr.substring(0, 4)) - 1911; // 西元轉民國
      const month = parseInt(dateStr.substring(4, 6));       // 擷取月份
      const periodMonth = String(Math.ceil(month / 2) * 2).padStart(2, '0'); // 計算雙月期別
      period = `${year}${periodMonth}`;
    }
  }

  // 3. 格式判斷：遇到「個人」不加括號，有統編才組合
  let taxDisplay = '個人';
  if (taxID && taxID !== '0' && taxID !== '個人') {
    taxDisplay = `(${taxID}${companyName})`;
  }

  // 4. 輸出最終結果（包含事先鎖定好的 time 時間戳記）
  return {
    json: {
      invoice: '60118942', // 商家統編
      invoice_number: invoiceNumber,
      tax_id: taxID,
      company_name: companyName,
      invoice_date: invoiceDate,
      data_payload: JSON.stringify(dataObj),
      appKey: '7FwqIY6mNMt5XeLxudYO',

      // 💡 固定時間戳記
      time: Math.floor(Date.now() / 1000).toString(),

      // 輸出目標檔名格式：期別_發票號碼_統編公司_發票日期.pdf
      fileName: `${period}_${invoiceNumber}_${taxDisplay}_${invoiceDate}.pdf`
    }
  };
});

const time = Math.floor(Date.now() / 1000).toString();
const appKey = '7FwqIY6mNMt5XeLxudYO';

// 使用 map 確保處理進來的所有 10 筆發票
return items.map(item => {
  const invoiceNum = item.json['發票號碼'].toString().trim();

  // 依照文檔建構查詢物件
  const dataObj = { 
    "type": "invoice",
    "invoice_number": invoiceNum 
  };

  const dataPayload = JSON.stringify(dataObj);

  return {
    json: {
      time: time,
      data_payload: dataPayload,
      // 簽章必須包含 dataPayload
      raw_sign_string: dataPayload + time + appKey,
      invoice_number: invoiceNum
    }
  };
});

